Rules: 02, 07.6

```ts
import { z } from 'zod';
import { ok, err, type Result } from '@tenets/result';

const CreateInvoiceInput = z.object({
	customerId: z.string(),
	amountCents: z.number().int().positive(),
});
type CreateInvoiceInput = z.infer<typeof CreateInvoiceInput>;

type Invoice = { id: string; customerId: string; amountCents: number };

type CreateInvoiceError = { type: 'unknown_customer'; customerId: string };

function createInvoice(
	input: CreateInvoiceInput,
	knownCustomerIds: ReadonlySet<string>,
): Result<Invoice, CreateInvoiceError> {
	if (!knownCustomerIds.has(input.customerId)) {
		return err({ type: 'unknown_customer', customerId: input.customerId });
	}
	return ok({ id: crypto.randomUUID(), customerId: input.customerId, amountCents: input.amountCents });
}
```

`CreateInvoiceInput` parse (`safeParse`) belong at caller's boundary (HTTP route etc), not inside this function — keep `createInvoice` domain-pure. Skipped: schema-parsing wrapper here, add when this fn gets called direct from untrusted input.

